package com.ptms.controller;import com.ptms.dto.SettingsDto;import com.ptms.service.SettingsService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.Map;@RestController @RequestMapping("/api/settings") public class SettingsController{private final SettingsService s;public SettingsController(SettingsService s){this.s=s;}@GetMapping public SettingsDto get(){return s.get();}@PutMapping public SettingsDto save(@Valid @RequestBody SettingsDto q){return s.save(q);}@PostMapping("/ticket-number-reset/{hours}") public Map<String,Integer> reset(@PathVariable int hours){return Map.of("hours",hours,"cycle",s.resetManualCycle(hours));}}
